package agentfs

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"path"
	"strings"
	"time"

	"github.com/c4pt0r/agfs/agfs-server/pkg/filesystem"
	"github.com/c4pt0r/agfs/agfs-server/pkg/plugin"
)

var errIsDir = errors.New("is a directory")

// AgentFS implements filesystem.FileSystem: directory listings and metadata
// are deterministic (no LLM), file reads are generated by the agent and
// cached per skill TTL.
type AgentFS struct {
	reg        *SkillRegistry
	cache      *Cache
	agent      *Agent
	defaultTTL time.Duration
	startedAt  time.Time
	usage      string
}

func NewAgentFS(reg *SkillRegistry, agent *Agent, defaultTTL time.Duration, usage string) *AgentFS {
	return &AgentFS{
		reg:        reg,
		cache:      NewCache(),
		agent:      agent,
		defaultTTL: defaultTTL,
		startedAt:  time.Now(),
		usage:      usage,
	}
}

var (
	_ filesystem.FileSystem = (*AgentFS)(nil)
	_ filesystem.Truncater  = (*AgentFS)(nil)
)

func cleanPath(p string) string {
	return path.Clean("/" + p)
}

func splitSegments(p string) []string {
	p = cleanPath(p)
	if p == "/" {
		return nil
	}
	return strings.Split(strings.TrimPrefix(p, "/"), "/")
}

func fileInfo(name string, size int64, mtime time.Time) *filesystem.FileInfo {
	return &filesystem.FileInfo{
		Name:    name,
		Size:    size,
		Mode:    0444,
		ModTime: mtime,
		IsDir:   false,
		Meta:    filesystem.MetaData{Name: PluginName, Type: "file"},
	}
}

func dirInfo(name string, mtime time.Time) *filesystem.FileInfo {
	return &filesystem.FileInfo{
		Name:    name,
		Size:    0,
		Mode:    0555,
		ModTime: mtime,
		IsDir:   true,
		Meta:    filesystem.MetaData{Name: PluginName, Type: "directory"},
	}
}

// generate returns cached content or asks the agent. The effective TTL is
// the smallest TTL among the participating skills.
func (fs *AgentFS) generate(p string, skills []*Skill) ([]byte, error) {
	if data, ok := fs.cache.Get(p); ok {
		return data, nil
	}
	ttl := fs.defaultTTL
	for _, sk := range skills {
		if sk.TTL > 0 && sk.TTL < ttl {
			ttl = sk.TTL
		}
	}
	data, err := fs.agent.Generate(p, skills)
	if err != nil {
		return nil, err
	}
	fs.cache.Set(p, data, ttl)
	return data, nil
}

func (fs *AgentFS) generateArbitrary(p string) ([]byte, error) {
	selected := fs.agent.RouteSkills(p, fs.reg.List())
	return fs.generate(p, selected)
}

func (fs *AgentFS) Read(p string, offset int64, size int64) ([]byte, error) {
	p = cleanPath(p)
	if p == "/" || p == "/.skills" {
		return nil, errIsDir
	}
	if p == "/README.md" {
		return plugin.ApplyRangeRead([]byte(fs.usage), offset, size)
	}
	if strings.HasPrefix(p, "/.skills/") {
		base := path.Base(p)
		if !strings.HasSuffix(base, ".md") {
			return nil, filesystem.ErrNotFound
		}
		sk := fs.reg.Get(strings.TrimSuffix(base, ".md"))
		if sk == nil {
			return nil, filesystem.ErrNotFound
		}
		return plugin.ApplyRangeRead(sk.Raw, offset, size)
	}
	segs := splitSegments(p)
	if sk := fs.reg.Get(segs[0]); sk != nil {
		if len(segs) == 1 {
			return nil, errIsDir
		}
		if len(segs) == 2 && segs[1] == "README.md" {
			return plugin.ApplyRangeRead([]byte(RenderSkillReadme(sk)), offset, size)
		}
		data, err := fs.generate(p, []*Skill{sk})
		if err != nil {
			return nil, err
		}
		return plugin.ApplyRangeRead(data, offset, size)
	}
	data, err := fs.generateArbitrary(p)
	if err != nil {
		return nil, err
	}
	return plugin.ApplyRangeRead(data, offset, size)
}

func (fs *AgentFS) Write(p string, data []byte, offset int64, flags filesystem.WriteFlag) (int64, error) {
	p = cleanPath(p)
	if !strings.HasPrefix(p, "/.skills/") {
		return 0, fmt.Errorf("%s: read-only, only /.skills/*.md is writable", p)
	}
	base := path.Base(p)
	if !strings.HasSuffix(base, ".md") || base == ".md" {
		return 0, fmt.Errorf("skill files must be named <skill>.md")
	}
	if flags&filesystem.WriteFlagAppend != 0 {
		if old := fs.reg.Get(strings.TrimSuffix(base, ".md")); old != nil {
			merged := make([]byte, 0, len(old.Raw)+len(data))
			merged = append(merged, old.Raw...)
			merged = append(merged, data...)
			data = merged
		}
	} else if offset >= 0 {
		return 0, fmt.Errorf("partial writes (offset >= 0) are not supported for skills")
	}
	sk, err := ParseSkill(base, data)
	if err != nil {
		return 0, err
	}
	fs.reg.Put(sk)
	fs.cache.InvalidatePath(p)
	fs.cache.InvalidatePrefix("/" + sk.Name + "/")
	return int64(len(data)), nil
}

func (fs *AgentFS) Remove(p string) error {
	p = cleanPath(p)
	if !strings.HasPrefix(p, "/.skills/") {
		return fmt.Errorf("%s: read-only filesystem", p)
	}
	base := path.Base(p)
	if !fs.reg.Remove(base) {
		return filesystem.ErrNotFound
	}
	fs.cache.InvalidatePrefix("/" + strings.TrimSuffix(base, ".md") + "/")
	return nil
}

func (fs *AgentFS) Stat(p string) (*filesystem.FileInfo, error) {
	p = cleanPath(p)
	switch p {
	case "/":
		return dirInfo("/", fs.startedAt), nil
	case "/.skills":
		return dirInfo(".skills", fs.startedAt), nil
	}
	if p == "/README.md" {
		return fileInfo("README.md", int64(len(fs.usage)), fs.startedAt), nil
	}
	if strings.HasPrefix(p, "/.skills/") {
		base := path.Base(p)
		if !strings.HasSuffix(base, ".md") {
			return nil, filesystem.ErrNotFound
		}
		sk := fs.reg.Get(strings.TrimSuffix(base, ".md"))
		if sk == nil {
			return nil, filesystem.ErrNotFound
		}
		return fileInfo(base, int64(len(sk.Raw)), sk.LoadedAt), nil
	}
	segs := splitSegments(p)
	if sk := fs.reg.Get(segs[0]); sk != nil {
		if len(segs) == 1 {
			return dirInfo(sk.Name, sk.LoadedAt), nil
		}
		if len(segs) == 2 && segs[1] == "README.md" {
			r := RenderSkillReadme(sk)
			return fileInfo("README.md", int64(len(r)), sk.LoadedAt), nil
		}
		if ci, ok := fs.cache.GetInfo(p); ok {
			return fileInfo(path.Base(p), ci.Size, ci.ModTime), nil
		}
		return fileInfo(path.Base(p), 0, sk.LoadedAt), nil
	}
	if ci, ok := fs.cache.GetInfo(p); ok {
		return fileInfo(path.Base(p), ci.Size, ci.ModTime), nil
	}
	return fileInfo(path.Base(p), 0, fs.startedAt), nil
}

func (fs *AgentFS) ReadDir(p string) ([]filesystem.FileInfo, error) {
	p = cleanPath(p)
	switch p {
	case "/":
		entries := []filesystem.FileInfo{
			*fileInfo("README.md", int64(len(fs.usage)), fs.startedAt),
			*dirInfo(".skills", fs.startedAt),
		}
		for _, sk := range fs.reg.List() {
			entries = append(entries, *dirInfo(sk.Name, sk.LoadedAt))
		}
		return entries, nil
	case "/.skills":
		var entries []filesystem.FileInfo
		for _, sk := range fs.reg.List() {
			entries = append(entries, *fileInfo(sk.FileName, int64(len(sk.Raw)), sk.LoadedAt))
		}
		return entries, nil
	}
	segs := splitSegments(p)
	if sk := fs.reg.Get(segs[0]); sk != nil && len(segs) == 1 {
		r := RenderSkillReadme(sk)
		entries := []filesystem.FileInfo{*fileInfo("README.md", int64(len(r)), sk.LoadedAt)}
		seen := map[string]bool{"README.md": true}
		for _, f := range sk.Files {
			if !seen[f.Name] {
				seen[f.Name] = true
				entries = append(entries, *fileInfo(f.Name, 0, sk.LoadedAt))
			}
		}
		for _, ci := range fs.cache.ListPrefix("/" + sk.Name + "/") {
			name := path.Base(ci.Path)
			if !seen[name] {
				seen[name] = true
				entries = append(entries, *fileInfo(name, ci.Size, ci.ModTime))
			}
		}
		return entries, nil
	}
	return nil, fmt.Errorf("not a directory: %s", p)
}

func (fs *AgentFS) Create(p string) error {
	return fmt.Errorf("%s: read-only, write SKILL.md files under /.skills/ instead", cleanPath(p))
}

func (fs *AgentFS) Mkdir(p string, perm uint32) error {
	return fmt.Errorf("%s: agentfs is read-only outside /.skills/", cleanPath(p))
}

func (fs *AgentFS) RemoveAll(p string) error {
	p = cleanPath(p)
	if strings.HasPrefix(p, "/.skills/") {
		return fs.Remove(p)
	}
	return fmt.Errorf("%s: read-only filesystem", p)
}

func (fs *AgentFS) Rename(oldPath, newPath string) error {
	return errors.New("rename is not supported in agentfs")
}

func (fs *AgentFS) Chmod(p string, mode uint32) error {
	return errors.New("chmod is not supported in agentfs")
}

func (fs *AgentFS) Open(p string) (io.ReadCloser, error) {
	data, err := fs.Read(p, 0, -1)
	if err != nil && !errors.Is(err, io.EOF) {
		return nil, err
	}
	return io.NopCloser(bytes.NewReader(data)), nil
}

func (fs *AgentFS) OpenWrite(p string) (io.WriteCloser, error) {
	return nil, fmt.Errorf("%s: read-only, only Write to /.skills/*.md is supported", cleanPath(p))
}

// Truncate is a no-op so shell redirections keep working.
func (fs *AgentFS) Truncate(p string, size int64) error {
	return nil
}
